const observerOptions={threshold:0.1,rootMargin:'0px 0px-50px 0px'};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animate-in');observer.unobserve(entry.target)}})},observerOptions);const sections=document.querySelectorAll('section');sections.forEach((section,index)=>{if(index>0){observer.observe(section)}});const addStaggerEffect=()=>{const cardContainers=document.querySelectorAll('.features-grid,.how-it-works-grid,.stats-grid,.testimonials-grid');cardContainers.forEach(container=>{const cards=container.querySelectorAll('.feature-card,.how-card,.stat-card,.testimonial-card');cards.forEach((card,index)=>{card.style.opacity='0';card.style.transform='translateY(20px)';card.style.transition=`opacity 0.6s ease ${index*0.1}s,transform 0.6s ease ${index*0.1}s`});const cardObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const cards=entry.target.querySelectorAll('.feature-card,.how-card,.stat-card,.testimonial-card');cards.forEach(card=>{card.style.opacity='1';card.style.transform='translateY(0)'});cardObserver.unobserve(entry.target)}})},observerOptions);cardObserver.observe(container)})};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',addStaggerEffect)}else{addStaggerEffect()}const initTextReveal=()=>{const heading=document.querySelector('.efficiency-heading');if(!heading)return;const originalText=heading.textContent.trim();const words=originalText.split(/(\s+)/);heading.innerHTML='';const wordElements=[];let wordIndex=0;words.forEach((segment)=>{if(segment.trim()===''){heading.appendChild(document.createTextNode(segment))}else{const wordSpan=document.createElement('span');wordSpan.className='reveal-word';wordSpan.textContent=segment;wordSpan.dataset.wordIndex=wordIndex;heading.appendChild(wordSpan);wordElements.push(wordSpan);wordIndex++}});heading._wordElements=wordElements;heading._totalWords=wordElements.length;const updateWordReveal=()=>{const section=heading.closest('.efficiency-section');if(!section)return;const windowHeight=window.innerHeight;const sectionRect=section.getBoundingClientRect();const sectionTop=sectionRect.top;const sectionBottom=sectionRect.bottom;const startPoint=windowHeight*0.7;const endPoint=windowHeight*0.2;const range=startPoint-endPoint;let progress=0;if(sectionTop<=startPoint&&sectionTop>=endPoint){progress=(startPoint-sectionTop)/range;progress=Math.max(0,Math.min(1,progress))}else if(sectionTop<endPoint){progress=1}else{progress=0}const wordsToShow=Math.floor(progress*wordElements.length);wordElements.forEach((wordEl,index)=>{if(index<wordsToShow){wordEl.classList.add('revealed')}else{wordEl.classList.remove('revealed')}})};let ticking=false;const handleScroll=()=>{if(!ticking){window.requestAnimationFrame(()=>{updateWordReveal();ticking=false});ticking=true}};updateWordReveal();window.addEventListener('scroll',handleScroll,{passive:true});window.addEventListener('resize',handleScroll,{passive:true})};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initTextReveal)}else{initTextReveal()}const initBackgroundTransition=()=>{const efficiencySection=document.querySelector('.efficiency-section');const customerTrustSection=document.querySelector('.customer-trust-section');if(!efficiencySection||!customerTrustSection)return;const updateBackgroundTransition=()=>{const windowHeight=window.innerHeight;const efficiencyRect=efficiencySection.getBoundingClientRect();const customerTrustRect=customerTrustSection.getBoundingClientRect();const efficiencyBottom=efficiencyRect.bottom;const transitionStart=windowHeight;const transitionEnd=windowHeight*0.5;const transitionRange=transitionStart-transitionEnd;let opacity=0;if(efficiencyBottom<=transitionStart&&efficiencyBottom>=transitionEnd){opacity=(transitionStart-efficiencyBottom)/transitionRange;opacity=Math.max(0,Math.min(1,opacity))}else if(efficiencyBottom<transitionEnd){opacity=1}else{opacity=0}efficiencySection.style.setProperty('--transition-opacity',opacity)};const style=document.createElement('style');style.textContent=` .efficiency-section::after{opacity:var(--transition-opacity,0)}`;document.head.appendChild(style);let ticking=false;const handleScroll=()=>{if(!ticking){window.requestAnimationFrame(()=>{updateBackgroundTransition();ticking=false});ticking=true}};updateBackgroundTransition();window.addEventListener('scroll',handleScroll,{passive:true});window.addEventListener('resize',handleScroll,{passive:true})};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initBackgroundTransition)}else{initBackgroundTransition()}const initGetStartedFormTransition=()=>{const getStartedFormSection=document.querySelector('.get-started-form-section');const customerTrustSection=document.querySelector('.customer-trust-section');if(!getStartedFormSection||!customerTrustSection)return;const updateBackgroundTransition=()=>{const windowHeight=window.innerHeight;const getStartedFormRect=getStartedFormSection.getBoundingClientRect();const getStartedFormBottom=getStartedFormRect.bottom;const transitionStart=windowHeight;const transitionEnd=windowHeight*0.5;const transitionRange=transitionStart-transitionEnd;let opacity=0;if(getStartedFormBottom<=transitionStart&&getStartedFormBottom>=transitionEnd){opacity=(transitionStart-getStartedFormBottom)/transitionRange;opacity=Math.max(0,Math.min(1,opacity))}else if(getStartedFormBottom<transitionEnd){opacity=1}else{opacity=0}getStartedFormSection.style.setProperty('--transition-opacity',opacity)};const style=document.createElement('style');style.textContent=` .get-started-form-section::after{opacity:var(--transition-opacity,0)}`;document.head.appendChild(style);let ticking=false;const handleScroll=()=>{if(!ticking){window.requestAnimationFrame(()=>{updateBackgroundTransition();ticking=false});ticking=true}};updateBackgroundTransition();window.addEventListener('scroll',handleScroll,{passive:true});window.addEventListener('resize',handleScroll,{passive:true})};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initGetStartedFormTransition)}else{initGetStartedFormTransition()}const initCounterAnimation=()=>{const statNumbers=document.querySelectorAll('.performance-stat-number[data-target]');if(!statNumbers.length){console.log('No stat numbers found');return}console.log('Counter animation initialized,found',statNumbers.length,'stat numbers');const duration=2000;const frameDuration=1000/60;const totalFrames=Math.round(duration/frameDuration);const easeOutQuad=(t)=>t*(2-t);const animateCounter=(element)=>{const target=parseInt(element.dataset.target,10);console.log('Animating counter to',target);let frame=0;const counter=setInterval(()=>{frame++;const progress=easeOutQuad(frame/totalFrames);const currentValue=Math.round(target*progress);element.textContent=currentValue+'%';if(frame===totalFrames){clearInterval(counter);element.textContent=target+'%'}},frameDuration)};const counterObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{console.log('Intersection observed:',entry.isIntersecting,'ratio:',entry.intersectionRatio);if(entry.isIntersecting){const statsInView=entry.target.querySelectorAll('.performance-stat-number[data-target]');console.log('Stats in view:',statsInView.length);statsInView.forEach((stat,index)=>{setTimeout(()=>{animateCounter(stat)},index*200)});counterObserver.unobserve(entry.target)}})},{threshold:0.1,rootMargin:'0px 0px-50px 0px'});const statsSection=document.querySelector('.ai-performance-section');if(statsSection){console.log('Observing ai-performance-section');counterObserver.observe(statsSection)}else{console.log('ai-performance-section not found')}};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initCounterAnimation)}else{initCounterAnimation()}